input.command:
cd /workspace; sqlite3 data/service.sqlite '.schema' 2>/dev/null || python3 -c "
import sqlite3;c=sqlite3.connect('data/service.sqlite')
for r in c.execute('select sql from sqlite_master'):print(r[0])"

cd /workspace; python -m service fill --db data/service.sqlite --out /tmp/orig && head -c 300 /tmp/orig/readout.json; python3 /tmp/q.py "
select sum(confirmed_qty=0), sum(confirmed_qty<requested_qty), sum(confirmed_qty>requested_qty), sum(delivered_qty is null), sum(cancelled_by_customer=1 and delivered_qty>0) from order_lines;
select sum(amended_qty>confirmed_qty), sum(amended_qty<confirmed_qty), sum(amended_qty=confirmed_qty) from order_lines where amended_qty is not null;
with b as (select * from order_lines where cancelled_by_customer=0 and requested_delivery_date>='2026-04-06' and requested_delivery_date<'2026-07-06')
select count(*), sum(delivered_qty>=confirmed_qty), sum(delivered_qty>=coalesce(amended_qty,confirmed_qty)), sum(amended_qty is not null), sum(amended_qty is not null and delivered_qty>=confirmed_qty), sum(amended_qty is not null and delivered_qty>=amended_qty), sum(delivered_qty>=requested_qty) from b;
select typeof(confirmed_qty), count(*) from order_lines group by 1;
select count(*) from order_lines where requested_delivery_date>='2026-07-06';
"

cd /workspace; python3 /tmp/q.py "
with b as (select l.*, g.received_qty, g.received_on from order_lines l left join goods_receipts g using(line_id) where cancelled_by_customer=0 and requested_delivery_date>='2026-04-06' and requested_delivery_date<'2026-07-06')
select count(*), sum(received_qty is null), sum(received_qty<delivered_qty), sum(received_qty>delivered_qty), sum(received_qty>=confirmed_qty), sum(received_qty>=coalesce(amended_qty,confirmed_qty)) from b;
with b as (select l.*, g.received_qty from order_lines l left join goods_receipts g using(line_id) where cancelled_by_customer=0 and requested_delivery_date>='2026-04-06' and requested_delivery_date<'2026-07-06')
select account_id, count(*), sum(delivered_qty>=confirmed_qty), sum(received_qty<delivered_qty), sum(received_qty>=confirmed_qty) from b group by 1;
"

cd /workspace; python3 /tmp/q.py "
select t.claim_type, count(*), sum(r.line_id is not null) ret, sum(l.delivered_qty>=l.confirmed_qty) filled, sum(l.requested_delivery_date>='2026-04-06' and l.requested_delivery_date<'2026-07-06') inper, sum(l.delivered_qty>=l.requested_qty) full_req, sum(l.amended_qty is not null) amended from shortfall_tickets t join order_lines l using(line_id) left join returns r using(line_id) group by 1;
select r.reason_code, count(*) from shortfall_tickets t join returns r using(line_id) group by 1;
select count(*) from shortfall_tickets t left join order_lines l using(line_id) where l.line_id is null;
with b as (select * from order_lines where cancelled_by_customer=0 and requested_delivery_date>='2026-04-06' and requested_delivery_date<'2026-07-06')
select account_id, round(100.0*sum(delivered_qty>=coalesce(amended_qty,confirmed_qty))/count(*),2) from b group by 1 having account_id<='ACC-004';
"
